cd /workspace && cat > src/parser.ts <<'EOF'
import { ProfilePatch } from './types';

const invalid = () => new Error('invalid profile');

function readData(obj: object, key: string): unknown {
  const desc = Object.getOwnPropertyDescriptor(obj, key);
  if (!desc || !('value' in desc)) throw invalid();
  return desc.value;
}

function parseDisplayName(value: unknown): string | null {
  if (value === null) return null;
  if (typeof value !== 'string') throw invalid();
  const trimmed = value.trim();
  if (trimmed.length < 1 || trimmed.length > 40) throw invalid();
  return trimmed;
}

function parseTags(value: unknown): string[] {
  if (value === null) return [];
  if (!Array.isArray(value)) throw invalid();
  if (value.length > 5) throw invalid();
  const result: string[] = [];
  const seen = new Set<string>();
  for (let i = 0; i < value.length; i++) {
    const desc = Object.getOwnPropertyDescriptor(value, String(i));
    if (!desc || !('value' in desc) || typeof desc.value !== 'string') throw invalid();
    const tag = desc.value.trim();
    if (tag.length < 1 || tag.length > 12 || seen.has(tag)) throw invalid();
    seen.add(tag);
    result.push(tag);
  }
  return result;
}

export function parseProfile(input: unknown): ProfilePatch {
  if (typeof input !== 'object' || input === null || Array.isArray(input)) throw invalid();
  const proto = Object.getPrototypeOf(input);
  if (proto !== Object.prototype && proto !== null) throw invalid();
  for (const key of Reflect.ownKeys(input)) {
    if (key !== 'displayName' && key !== 'tags') throw invalid();
  }
  let displayName: ProfilePatch['displayName'] = { kind: 'keep' };
  let tags: ProfilePatch['tags'] = { kind: 'keep' };
  if (Object.prototype.hasOwnProperty.call(input, 'displayName')) {
    displayName = { kind: 'set', value: parseDisplayName(readData(input, 'displayName')) };
  }
  if (Object.prototype.hasOwnProperty.call(input, 'tags')) {
    tags = { kind: 'set', value: parseTags(readData(input, 'tags')) };
  }
  return { displayName, tags };
}
EOF
cat > src/service.ts <<'EOF'
import { Profile } from './types';
import { parseProfile } from './parser';
export class ProfileService {
  constructor(readonly profile: Profile) {}
  patch(input: unknown): Profile {
    // Parse and validate everything first so a failure leaves storage untouched.
    const parsed = parseProfile(input);
    if (parsed.displayName.kind === 'set') this.profile.displayName = parsed.displayName.value;
    if (parsed.tags.kind === 'set') this.profile.tags = [...parsed.tags.value];
    return this.profile;
  }
}
EOF
cat >> checks/public.cjs <<'EOF'

{
  const s = new ProfileService({ displayName: 'a', tags: ['x'] });
  const bad = [undefined, 1, 'x', [], { foo: 1 }, { displayName: 1 }, { displayName: '  ' }, { displayName: 'x'.repeat(41) },
    { tags: 'a' }, { tags: [1] }, { tags: ['a', ' a '] }, { tags: ['  '] }, { tags: ['x'.repeat(13)] },
    { tags: ['1', '2', '3', '4', '5', '6'] }, { displayName: 'ok', tags: [1] }, Object.create({ displayName: 'x' }), new Date()];
  for (const b of bad) assert.throws(() => s.patch(b), /invalid profile/);
  assert.deepEqual(s.profile, { displayName: 'a', tags: ['x'] });
  assert.deepEqual(s.patch({}), { displayName: 'a', tags: ['x'] });
  const tags = [' p ', 'q'];
  const input = { displayName: ' Bob ', tags };
  assert.deepEqual(s.patch(input), { displayName: 'Bob', tags: ['p', 'q'] });
  assert.notEqual(s.profile.tags, tags);
  assert.deepEqual(tags, [' p ', 'q']);
  assert.equal(input.displayName, ' Bob ');
  assert.deepEqual(s.patch({ displayName: null, tags: null }), { displayName: null, tags: [] });
  s.patch({ tags: ['z'] });
  assert.deepEqual(s.patch({ tags: [] }).tags, []);
  const np = Object.assign(Object.create(null), { displayName: 'n' });
  assert.equal(s.patch(np).displayName, 'n');
}
EOF
tsc -p tsconfig.json && node checks/public.cjs && echo OK

